usage:
package main

import (
	"context"
	"fmt"
	"os"

	"github.com/example/widgetco"
	"github.com/example/widgetco/option"
	"github.com/example/widgetco/packages/param"
)

func main() {
	client := widgetco.NewClient(
		option.WithAPIKey(os.Getenv("WIDGETCO_API_KEY")),
	)
	result, err := client.Gadgets.List(
		context.TODO(),
		widgetco.GadgetListParams{
			Limit: param.NewOpt[int64](10),
			Cursor: param.NewOpt[string]("cur_abc"),
		},
	)
	if err != nil {
		panic(err.Error())
	}
	fmt.Printf("%+v\n", result)
}
